WITH base AS (SELECT * FROM order_items WHERE order_id IN (5, 12, 15) AND (quantity BETWEEN 3 AND 4 OR unit_price BETWEEN 120 AND 220)), OrderItemsStats AS (SELECT CASE WHEN unit_price >= 400 THEN 'high' WHEN unit_price >= 170 THEN 'mid' ELSE 'low' END AS unit_price_bucket, ROUND(STDDEV(quantity), 2) AS stddev_quantity FROM base GROUP BY CASE WHEN unit_price >= 400 THEN 'high' WHEN unit_price >= 170 THEN 'mid' ELSE 'low' END) SELECT * FROM OrderItemsStats WHERE stddev_quantity < 23 ORDER BY unit_price_bucket ASC, stddev_quantity ASC;
